// JSX 编译结果（旧 runtime 示例；React 17+ automatic runtime 通常是 jsx/jsxs）
const element = React.createElement(
  'div',
  { className: 'app' },
  React.createElement('h1', null, 'Hello'),
  React.createElement('p', null, 'World')
);

// 虚拟DOM结构
const vnode = {
  type: 'div',
  props: {
    className: 'app',
    children: [
      { type: 'h1', props: { children: 'Hello' } },
      { type: 'p', props: { children: 'World' } }
    ]
  }
};

// Fiber节点结构
const fiber = {
  tag: 'HostComponent', // 组件类型
  type: 'div',          // 标签/组件
  stateNode: domNode,   // DOM节点
  props: {},            // 属性
  child: childFiber,    // 第一个子节点
  sibling: nextFiber,   // 下一个兄弟节点
  return: parentFiber,  // 父节点
  alternate: prevFiber, // 对应的另一棵树的节点
  effectTag: 'UPDATE',  // 副作用标记
  lanes: 0b0001,        // 优先级
};

// 简化的工作循环
function workLoop(deadline) {
  while (nextUnitOfWork && !shouldYield()) {
    nextUnitOfWork = performUnitOfWork(nextUnitOfWork);
  }
  if (!nextUnitOfWork) {
    commitRoot(); // 进入Commit阶段
  } else {
    requestIdleCallback(workLoop); // 让出控制权
  }
}

// Diff算法简化逻辑
function diffChildren(oldFiber, newChildren) {
  let oldFiberMap = new Map();
  let fiber = oldFiber;
  while (fiber) {
    oldFiberMap.set(fiber.key || fiber.index, fiber);
    fiber = fiber.sibling;
  }
  // 按key匹配，复用或创建新节点
}
